 *     correctly out of them, naming his four materials mat_bm_body / _eye /
 *     _head / _head_c against textures mario_body / _eye_1 / _head. That is
 *     empirical rather than read out of matched ARM, and it is flagged as such
 *     in notes/system-provenance.md.
 *
 * Field NAMES are inferred from that behaviour and cannot change codegen.
 * Offsets and strides are pinned by the bytes. Records keep explicit
 * padding for the parts no matched function touches yet.
 */

struct BMD_Bone {
    u32 unk_00;
    Ptr<void> unk_04;          /* 0x04 - file-relative, fixed up on load */
    u8 pad_08[0x28];
    /* 0x30 - length of materialIds: bounds the material walks in
       dScStage_c::RenderModel and RenderModelTransparent */
    u16 numMaterials;
    u8 pad_32[0x2];
    Ptr<u8> materialIds;       /* 0x34 - per-bone material index list */
    Ptr<void> unk_38;          /* 0x38 - file-relative, fixed up on load */
    u32 unk_3c;
};

/* One 0x10-byte display-list record. dExtSimpleModel_c::UpdateFileOffsets rebases the
   words at +0x04 and +0x0c, which is the evidence that both are file-relative
   offsets; the host port reads +0x08 as the byte size of the stream at +0x0c
   and feeds that stream straight to the geometry engine (port/ntr/bmd.cpp). */
struct BMD_DisplayList {
    u32 unk_00;
    Ptr<void> unk_04;          /* 0x04 - file-relative, fixed up on load */
    u32 size;              /* 0x08 - bytes of packed DS commands at data */
    Ptr<void> data;            /* 0x0c - file-relative, fixed up on load */
};

/* The display lists are grouped: an array of these, one per group. */
struct BMD_DisplayListGroup {
    u32 numLists;              /* 0x00 - bounds the loop over lists */
    Ptr<struct BMD_DisplayList> lists;  /* 0x04 - file-relative, fixed up on load */
};

struct BMD_Material {
    Ptr<char> name;            /* 0x00 - file-relative, fixed up on load */
    u32 textureId;         /* 0x04 - index into BMD_File::textures */
    u32 paletteId;         /* 0x08 - index into BMD_File::palettes */
    u8 pad_0c[0x14];
    u32 texImageParam;     /* 0x20 - ORed with the texture's flags by func_02046bbc */
    u32 flags;             /* 0x24 - bit 31 hides the material */
    u8 pad_28[0x8];
};

struct BMD_Texture {
    Ptr<char> name;            /* 0x00 - file-relative, fixed up on load */
    Ptr<char> data;            /* 0x04 */
    u32 size;              /* 0x08 */
    u32 unk_0c;
    u32 flags;             /* 0x10 - format in bits 26..28; VRAM offset >> 3
                                     packed into the low 16 bits on load */
};

struct BMD_Palette {
    Ptr<char> name;            /* 0x00 - file-relative, fixed up on load */
    Ptr<char> data;            /* 0x04 */
    u32 size;              /* 0x08 */
    u32 vramOffset;        /* 0x0c - written by dExtSimpleModel_c::LoadTexAndPal */
};

struct BMD_File {
    u32 scaleShift;            /* 0x00 */
    u32 numBones;              /* 0x04 */
    Ptr<struct BMD_Bone> bones;    /* 0x08 - 0x40-byte records */
    u32 numDisplayListGroups;  /* 0x0c - bounds the loop over the table below */
    Ptr<struct BMD_DisplayListGroup> displayListGroups;  /* 0x10 */
    u32 numTextures;           /* 0x14 */
    Ptr<struct BMD_Texture> textures;   /* 0x18 */
    u32 numPalettes;           /* 0x1c */
    Ptr<struct BMD_Palette> palettes;   /* 0x20 */
    u32 numMaterials;          /* 0x24 */
    Ptr<struct BMD_Material> materials; /* 0x28 */
    Ptr<void> unk_2c;              /* 0x2c - fixed up on load */
    u32 unk_30;                /* 0x30 - guards the block below */
    Ptr<void> unk_34;              /* 0x34 - block of four pointers, all fixed up */
};

