struct System;

/* One 0x20-byte entry in the manager's effect-definition table. The table
   stride and the leading pointer are fixed by Manager::AddSystem and
   pk_SetSelfDestructFlag; the remaining fields are not reached by either. */
struct SystemDefinition {
    struct Data {
        u32 flags;          /* 0x00 - bit 14 requests self-destruction */
        u32 callbackParam;  /* 0x04 - written by edStarKiraCallback_c */
        u8 pad_008[0x20];
        u16 callbackValue;  /* 0x28 - loaned to a live System */
    };

    Ptr<Data> data;             /* 0x00 */
    u8 pad_004[0x1c];
};

struct Manager {
    /* The three manager lists are the same two-word intrusive-list heads used
       by pk_func_0204d958/pk_func_0204d9a0. Element types differ. AddSystem names
       the system lists; the third list is the free-particle pool. */
    struct SystemList {
        Ptr<System> head; /* 0x00 */
        s32 count;    /* 0x04 */
    };

    /* pk_func_0204a4c8 fills this with `b` nodes of 0x44 bytes, and func_02049d60
       hands it to a system. The node is not Particle::Element (0x30). */
    struct FreeList {
        Ptr<void> head; /* 0x00 */
        s32 count;  /* 0x04 */
    };

    Ptr<void> allocator;                /* 0x00 */
    SystemList mActiveSystems;      /* 0x04 */
    SystemList mFreeSystems;        /* 0x0c */
    FreeList mFreeParticles;        /* 0x14 */
    Ptr<SystemDefinition> mDefinitions; /* 0x1c */
    Ptr<void> unk_020;                  /* 0x20 */
    u16 unk_024;                    /* 0x24 */
    u16 unk_026;                    /* 0x26 */
    u16 unk_028;                    /* 0x28 */
    u16 unk_02a;                    /* 0x2a */
    u16 unk_02c;                    /* 0x2c */
    u16 unk_02e;                    /* 0x2e */
    u8 pad_030[0xc];


};

