/* ROM layout under mwccarm; host ABI divergence is tracked separately. */
typedef char Matrix3x3_size_must_be_0x24[sizeof(Matrix3x3) == 0x24 ? 1 : -1];
#endif
/* With `r` first and 0x24 bytes wide, these two also pin `t` to 0x24. */
